<?php require 'partials.php';update_finalists();$games=db()->query('SELECT * FROM games ORDER BY play_date,field DESC,play_time')->fetchAll();header_html('Schedule','schedule');$last='';foreach($games as $g):if($last!==$g['play_date']):if($last)echo '</tbody></table></div></section>';$last=$g['play_date'];?><section class="card"><div class="section-title"><h2><?=date('l, j F Y',strtotime($last))?></h2></div><div class="table"><table><thead><tr><th>Game</th><th>Time</th><th class="hide-sm">Field</th><th>Match-up</th><th>Score</th><th>Status</th></tr></thead><tbody><?php endif;?><tr><td><?=$g['game_no']?></td><td><?=$g['play_time']?></td><td class="hide-sm"><?=h($g['field'])?></td><td><b><?=h($g['team1'])?></b><br><span class="muted">vs <?=h($g['team2'])?> · <?=h($g['phase'])?></span></td><td class="score"><?=is_null($g['score1'])?'–':$g['score1']?> : <?=is_null($g['score2'])?'–':$g['score2']?></td><td><?=status_badge($g['status'])?></td></tr><?php endforeach;if($last)echo '</tbody></table></div></section>';footer_html();?>